builder.Services.AddHttpClient<GitHubClient>(client =>
{
    client.BaseAddress = new Uri("https://api.github.com/");
    client.DefaultRequestHeaders.Add("User-Agent", "Quotient");
    client.Timeout = TimeSpan.FromSeconds(10);
})
.AddHttpMessageHandler<AuthHandler>();

public sealed class GitHubClient(HttpClient http)
{
    public async Task<Repo?> GetRepoAsync(string owner, string name, CancellationToken token)
    {
        using var response = await http.GetAsync($"repos/{owner}/{name}", token);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Repo>(cancellationToken: token);
    }
}
